import{_ as t,K as l,a as o,c as r,ac as a,b as s,q as i}from"./chunks/framework.BSuaGltH.js";const H=JSON.parse('{"title":"五子棋：先手、攻防与关键落点","description":"先处理立即成五，再通过双向冲四例子理解一手多用，避免为了进攻忘记防守。","frontmatter":{"title":"五子棋：先手、攻防与关键落点","description":"先处理立即成五，再通过双向冲四例子理解一手多用，避免为了进攻忘记防守。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"五子棋入门","summary":"先处理立即成五，再通过双向冲四例子理解一手多用，避免为了进攻忘记防守。","status":"active","related":[{"title":"五子棋：自由规则与禁手规则的区别","link":"/life/personal/chess/gomoku/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"五子棋：活三、冲四与连续威胁","link":"/life/personal/chess/gomoku/threats","kind":"棋类入门","scope":"general","audience":"general"},{"title":"五子棋：识别漏防与重复错误","link":"/life/personal/chess/gomoku/review","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"五子棋：活三、冲四与连续威胁","link":"/life/personal/chess/gomoku/threats"},"next":{"text":"五子棋：识别漏防与重复错误","link":"/life/personal/chess/gomoku/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"五子棋：活三、冲四与连续威胁","link":"/life/personal/chess/gomoku/threats"},"next":{"text":"五子棋：识别漏防与重复错误","link":"/life/personal/chess/gomoku/review"}},"headers":[],"relativePath":"life/personal/chess/gomoku/attack-defense.md","filePath":"life/personal/chess/gomoku/attack-defense.md"}'),p={name:"life/personal/chess/gomoku/attack-defense.md"},c={class:"chess-example"},d={class:"chess-figure"};function h(u,e,_,g,k,m){const n=l("ArticleImage");return o(),r("div",null,[e[1]||(e[1]=a('<h1 id="五子棋-先手、攻防与关键落点" tabindex="-1">五子棋：先手、攻防与关键落点 <a class="header-anchor" href="#五子棋-先手、攻防与关键落点" aria-label="Permalink to &quot;五子棋：先手、攻防与关键落点&quot;">​</a></h1><p>所谓先手，是你的威胁足够紧迫，迫使对方先回应；不是“我这一手看起来很积极”。新手可以先按紧急程度选择，而不用背复杂开局。</p><p>本文用自由练习规则，棋盘坐标 A～O、1～15。黑 X、白 O，点为空。所有局部例子都假设其他区域没有更快的成五威胁。</p><h2 id="每手先检查三个层次" tabindex="-1">每手先检查三个层次 <a class="header-anchor" href="#每手先检查三个层次" aria-label="Permalink to &quot;每手先检查三个层次&quot;">​</a></h2><p>第一层：我现在能否直接成五？能就先赢，不必为了挡对方的四放弃自己的胜着。</p><p>第二层：对方下一手能否直接成五？自己不能直接赢时，必须消除威胁。若对方有两个不同的成五点，而你无法一手同时消除，也没有自己的立即胜着，通常已经来不及普通防守。</p><p>第三层：双方暂时都不能成五，再考虑做活三、改善连接或堵对方发展点。</p><h2 id="只挡最明显的一条线为什么不够" tabindex="-1">只挡最明显的一条线为什么不够 <a class="header-anchor" href="#只挡最明显的一条线为什么不够" aria-label="Permalink to &quot;只挡最明显的一条线为什么不够&quot;">​</a></h2><p>白在 D8、E8、F8、G8，C8 被黑占着，H8 空。轮黑，白的直接胜点是 H8。黑若在别处做一个活三，白下 H8 就结束了。活三“有潜力”，但不能比马上输棋更优先。</p><p>正确的练习方法是先黑 H8，挡住白的唯一胜点，再观察自己的 H8 是否与附近黑子形成新的方向。好防守有时也能变成好进攻。</p><h2 id="一个一手制造两处威胁的例子" tabindex="-1">一个一手制造两处威胁的例子 <a class="header-anchor" href="#一个一手制造两处威胁的例子" aria-label="Permalink to &quot;一个一手制造两处威胁的例子&quot;">​</a></h2>',11)),s("div",c,[s("div",d,[s("p",null,[i(n,{src:"/images/chess/gomoku-double.svg",alt:"双向威胁 · 黑下 H8 之后。自由规则示例；成五点是 I8 与 H9。"})])]),e[0]||(e[0]=a(`<div class="chess-explanation"><p>摆黑 E8、F8、G8，以及 H5、H6、H7；白 D8、H4；轮黑，下图是相关区域。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>9  . . . . . .</span></span>
<span class="line"><span>8  O X X X . .</span></span>
<span class="line"><span>7  . . . . X .</span></span>
<span class="line"><span>6  . . . . X .</span></span>
<span class="line"><span>5  . . . . X .</span></span>
<span class="line"><span>4  . . . . O .</span></span>
<span class="line"><span>   D E F G H I</span></span></code></pre></div><p>黑下 H8。横向 E8～H8 四连，D8 已被白堵，唯一成五点 I8；纵向 H5～H8 四连，H4 已被白堵，唯一成五点 H9。白一次只能放一颗，堵 I8 后黑下 H9，堵 H9 后黑下 I8。</p><p>这个例子说明关键点 H8 同时服务两个方向。<strong>在连珠规则里黑方这一步会涉及双四禁手；本例只在明确约定的自由规则下成立。</strong> 白方或不同规则下不能直接照搬禁手结论。</p></div>`,1))]),e[2]||(e[2]=a('<h2 id="不要只盯落子点" tabindex="-1">不要只盯落子点 <a class="header-anchor" href="#不要只盯落子点" aria-label="Permalink to &quot;不要只盯落子点&quot;">​</a></h2><p>每次落下一子，检查经过它的四条线：横、竖、左上到右下、右上到左下。它可能在横向防守，却在斜向帮助对方形成更强威胁。</p><p>先手也是会用完的。例如冲四被堵后，如果你下一手没有新的直接威胁，对手就可以去别处下。不能把“我一直在攻击”当作对手必须一直防守的理由。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li>双向例中黑下 H8 后，白堵 I8，黑该下哪里？<strong>H9，纵向成五。</strong></li><li>若白本来另有一步成五，黑的双向威胁一定赢吗？<strong>不一定。</strong> 白可以先成五，棋局立即结束。</li><li>连珠执黑能照搬 H8 吗？<strong>不能。</strong> 必须先判断禁手，本例构成两条四，是专门的规则对照。</li></ol><p>下一盘设一个简单目标：落子前把双方的所有“下一步成五点”找出来，落子后再检查四个方向。先不漏一手胜负，再考虑更长计算。</p><p>规则差异参考：<a href="https://www.renju.net/rifrules/" target="_blank" rel="noopener noreferrer">RIF 连珠规则</a>、<a href="https://gomoku.renju.net/gomokurules/" target="_blank" rel="noopener noreferrer">国际 Gomoku 规则</a>。棋形为原创教学设计。</p>',7))])}const b=t(p,[["render",h]]);export{H as __pageData,b as default};
